import java.io.*;
import java.util.*;

public class I {
    private static final boolean isDebug = true;
    private static final String INPUT_FILE = "I";
    public static void main(String[] args) throws Exception {
        var inReader = isDebug
            ? new BufferedReader(new InputStreamReader(System.in))
            : new BufferedReader(new FileReader(INPUT_FILE + ".in"));
        var outWriter = isDebug
            ? new PrintWriter(System.out)
            : new PrintWriter(new BufferedWriter(new FileWriter(INPUT_FILE + ".out")));

        double N = Double.parseDouble(inReader.readLine());
        double P = Double.parseDouble(inReader.readLine());

        int answer = 0;
        for (int i = 0; i <= N; i++) {
            double term1 = (double)i * (i - 1) * (i - 2) / 6.0;
            double term2 = (double)i * (i - 1) * (N - i) / 2.0;
            double term3 = (double)i * (N - i) * (N - i - 1) / 4.0;
            double total = N * (N - 1) * (N - 2) / 6.0;
            double ratio = (term1 + term2 + term3) / total;

            if (ratio >= P) {
                answer = i;
                break;
            }
        }
        outWriter.println(answer);
        outWriter.close();
    }

    static class FenwickTree {
        private final int[] tree;

        FenwickTree(int n) {
            tree = new int[n + 15];
        }

        void add(int idx, int val) {
            for (++idx; idx < tree.length; idx += idx & -idx)
                tree[idx] ^= val;
        }

        int prefixXor(int idx) {
            int res = 0;
            for (++idx; idx > 0; idx -= idx & -idx)
                res ^= tree[idx];
            return res;
        }

        int query(int l, int r) {
            return prefixXor(r) ^ prefixXor(l - 1);
        }
    }

    static class LCAProcessor {
        static ArrayList<Integer>[] graph;
        static int[] inTime, outTime;
        static int[][] up;

        static void setup(int root) {
            int n = graph.length;
            inTime = new int[n];
            outTime = new int[n];
            int log = 32 - Integer.numberOfLeadingZeros(n);
            up = new int[n][log];
            dfs(root, root);
        }

        static void dfs(int v, int parent) {
            inTime[v] = ++timer;
            up[v][0] = parent;
            for (int j = 1; j < log; j++)
                up[v][j] = up[up[v][j - 1]][j - 1];
            for (int child : graph[v])
                if (child != parent) dfs(child, v);
            outTime[v] = ++timer;
        }

        static int timer = 0;

        static boolean isAnc(int u, int v) {
            return inTime[u] <= inTime[v] && outTime[u] >= outTime[v];
        }

        static int lca(int a, int b) {
            if (isAnc(a, b)) return a;
            if (isAnc(b, a)) return b;
            int log = up[0].length;
            for (int i = log - 1; i >= 0; i--)
                if (!isAnc(up[a][i], b))
                    a = up[a][i];
            return up[a][0];
        }
    }

    static class IOUtils {
        static String readString(BufferedReader br) throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = br.read()) <= ' ');
            while (c > ' ') {
                sb.append((char)c);
                c = br.read();
            }
            return sb.toString();
        }
    }
}
